import java.util.ArrayList;

public class Lote {

    private String codigo;
    private Nodo nodo;
    private ArrayList<Trabajo> trabajos;
    private ArrayList<Trabajo> trabajosConResultado;
    private String estado;

    // Aquí continúan el constructor y los métodos.

    public Lote(String codigo, Nodo nodo) {
        // Rechaza códigos vacíos o nulos.
        if (codigo == null || codigo.trim().isEmpty()) {
            throw new IllegalArgumentException(
                "El código del lote no puede estar vacío."
            );
        }

        // Comprueba que exista un nodo.
        if (nodo == null) {
            throw new IllegalArgumentException(
                "El lote debe tener un nodo."
            );
        }

        this.codigo = codigo.trim();
        this.nodo = nodo;
        this.trabajos = new ArrayList<>();
        this.trabajosConResultado = new ArrayList<>();
        this.estado = "EN_PREPARACION";

        // Reserva el nodo; si ya está ocupado, lanza una excepción.
        nodo.ocupar();
    }

    // Asigna un trabajo después de validar estado, compatibilidad y capacidad.
    public void asignarTrabajo(Trabajo trabajo) {
        // Solo permite asignaciones mientras se prepara el lote.
        if (!estado.equals("EN_PREPARACION")) {
            throw new IllegalStateException(
                "El lote no está en preparación."
            );
        }

        // Comprueba que exista un trabajo.
        if (trabajo == null) {
            throw new IllegalArgumentException(
                "Debe proporcionar un trabajo."
            );
        }

        // Evita agregar el mismo trabajo dos veces.
        if (trabajos.contains(trabajo)) {
            throw new IllegalStateException(
                "El trabajo ya pertenece a este lote."
            );
        }

        // Solo acepta trabajos que estén en cola.
        if (trabajo.getEstado() != Trabajo.EstadoTrabajo.EN_COLA) {
		throw new IllegalStateException("El trabajo debe estar en cola.");
}

        // Delega la decisión de compatibilidad al trabajo.
        if (!trabajo.esCompatibleCon(nodo)) {
            throw new IllegalArgumentException(
                "El trabajo no es compatible con el nodo."
            );
        }

        // Usa horas estimadas para comprobar la capacidad del nodo.
        if (calcularHorasAsignadas() + trabajo.getHorasEstimadas()
                > nodo.getCapacidadMaxima()) {
            throw new IllegalArgumentException(
                "El trabajo supera la capacidad disponible."
            );
        }

        // Cambia el estado del trabajo después de validar.
        trabajo.asignar();

        // Guarda el trabajo en el lote.
        trabajos.add(trabajo);
    }

    // Retira un trabajo y lo devuelve a la cola.
    public void retirarTrabajo(Trabajo trabajo) {
        // Impide retirar trabajos de un lote iniciado o cerrado.
        if (!estado.equals("EN_PREPARACION")) {
            throw new IllegalStateException(
                "El lote no está en preparación."
            );
        }

        // Verifica que el trabajo pertenezca a este lote.
        if (!trabajos.contains(trabajo)) {
            throw new IllegalArgumentException(
                "El trabajo no pertenece a este lote."
            );
        }

        // Cambia el estado del trabajo a EN_COLA.
        trabajo.retirar();

        // Elimina el trabajo de la lista del lote.
        trabajos.remove(trabajo);
    }

    // Inicia el lote después de validar todos sus trabajos.
    public void iniciar() {
        // Evita iniciar un lote que ya fue iniciado o cerrado.
        if (!estado.equals("EN_PREPARACION")) {
            throw new IllegalStateException(
                "El lote no está en preparación."
            );
        }

        // Rechaza lotes sin trabajos.
        if (trabajos.isEmpty()) {
            throw new IllegalStateException(
                "No se puede iniciar un lote vacío."
            );
        }

        // Revisa todos los trabajos antes de cambiar estados o cobrar.
        for (Trabajo trabajo : trabajos) {
            // Comprueba que cada trabajo esté asignado.
          if (trabajo.getEstado() != Trabajo.EstadoTrabajo.ASIGNADO) {
			throw new IllegalStateException("Todos los trabajos deben estar asignados.");
		}

            // Comprueba que cada trabajo tenga un intento disponible.
            if (trabajo.getIntentos() >= trabajo.getIntentosMaximos()) {
                throw new IllegalStateException(
                    "Un trabajo agotó sus intentos permitidos."
                );
            }
        }

        // Inicia los trabajos una vez que todos superaron las validaciones.
        for (Trabajo trabajo : trabajos) {
            // Incrementa el intento y aplica el cargo dentro del trabajo.
            trabajo.iniciarEjecucion();
        }

        // Actualiza el estado del lote.
        estado = "EN_EJECUCION";
    }

    // Registra una sola vez el resultado de un trabajo en este lote.
    public void registrarResultado(Trabajo trabajo, boolean completado) {
        // Solo acepta resultados cuando el lote está en ejecución.
        if (!estado.equals("EN_EJECUCION")) {
            throw new IllegalStateException(
                "El lote no está en ejecución."
            );
        }

        // Comprueba que el trabajo sea parte de este lote.
        if (!trabajos.contains(trabajo)) {
            throw new IllegalArgumentException(
                "El trabajo no pertenece a este lote."
            );
        }

        // Impide registrar dos resultados para el mismo trabajo en este lote.
        if (trabajosConResultado.contains(trabajo)) {
            throw new IllegalStateException(
                "El trabajo ya tiene resultado registrado en este lote."
            );
        }

        // Actualiza el trabajo según el resultado y sus intentos.
        trabajo.registrarResultado(completado);

        // Guarda que el resultado fue registrado correctamente.
        trabajosConResultado.add(trabajo);

        // Comprueba si todos los trabajos tienen resultado.
        if (trabajosConResultado.size() == trabajos.size()) {
            // Cierra el lote.
            estado = "CERRADO";

            // Libera el nodo para que pueda recibir otro lote.
            nodo.liberar();
        }
    }

    // Suma las horas estimadas de los trabajos del lote.
    public double calcularHorasAsignadas() {
        double total = 0.0;

        // Recorre todos los trabajos del lote.
        for (Trabajo trabajo : trabajos) {
            // Acumula sus horas estimadas.
            total += trabajo.getHorasEstimadas();
        }

        // Devuelve la suma obtenida.
        return total;
    }

    // Calcula las horas de capacidad restantes en el lote.
    public double calcularCapacidadDisponible() {
        // Resta las horas asignadas a la capacidad máxima del nodo.
        return nodo.getCapacidadMaxima() - calcularHorasAsignadas();
    }

    public String getCodigo() {
        return codigo;
    }

    public Nodo getNodo() {
        return nodo;
    }

    public String getEstado() {
        return estado;
    }

    public int getResultadosRegistrados() {
        return trabajosConResultado.size();
    }

    public ArrayList<Trabajo> getTrabajos() {
        // Devuelve una copia para evitar cambios externos a la lista interna.
        return new ArrayList<>(trabajos);
    }

    // Devuelve la descripción del lote para consultas y reportes.
    @Override
    public String toString() {
        // Presenta los datos del lote y el avance de sus resultados.
        return "Lote: " + codigo
                + " | Nodo: " + nodo.getCodigo()
                + " | Estado: " + estado
                + " | Horas asignadas: " + calcularHorasAsignadas()
                + " | Capacidad disponible: " + calcularCapacidadDisponible()
                + " | Resultados: " + trabajosConResultado.size()
                + "/" + trabajos.size();
    }
}